import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {organizationCustomPropertiesAppBuilder} from './config/app-builder'

import {businessCustomPropertiesSettingsRoute} from './routes/business-custom-properties-settings-route'
import {businessPropertyDefinitionRoute} from './routes/business-property-definition-route'
import {BusinessCustomPropertiesSettingsRoute} from './routes/BusinessCustomPropertiesSettingsRoute'
import {BusinessPropertyDefinitionRoute} from './routes/BusinessPropertyDefinitionRoute'
import {layoutRoute} from './routes/layout-route'
import {LayoutRoute} from './routes/LayoutRoute'
import {organizationCustomPropertiesSettingsRoute} from './routes/organization-custom-properties-settings-route'
import {OrganizationCustomPropertiesSettingsRoute} from './routes/OrganizationCustomPropertiesSettingsRoute'

export const organizationCustomPropertiesApp = organizationCustomPropertiesAppBuilder.createDataRouterAppFromRoutes([
  layoutRoute.toRoute({
    Component: LayoutRoute,
    children: [
      businessCustomPropertiesSettingsRoute.toRoute({Component: BusinessCustomPropertiesSettingsRoute}),
      businessPropertyDefinitionRoute.toRoute({Component: BusinessPropertyDefinitionRoute}),
      organizationCustomPropertiesSettingsRoute.toRoute({Component: OrganizationCustomPropertiesSettingsRoute}),
    ],
  }),
])
registerDataRouterApp(organizationCustomPropertiesApp)
