import {mainQuery} from '@github-ui/react-core/future/main-query'
import {organizationCustomPropertiesAppBuilder} from '../config/app-builder'
import type {OrganizationTarget, PropertyDefinition} from '@github-ui/custom-properties-types/org-properties'

export type BusinessPropertiesSettingsRouteResponse =
  | BusinessPropertiesListRouteResponse
  | BusinessSetValuesRouteResponse

export type BusinessPropertiesListRouteResponse = {
  activeTab: 'properties'
  totalCount: number
  pageCount: number
  definitions: PropertyDefinition[]
}

export type BusinessSetValuesRouteResponse = {
  activeTab: 'set-values'
  orgs: OrganizationTarget[]
  totalCount: number
  pageCount: number
  definitions: PropertyDefinition[]
}

export const businessCustomPropertiesSettingsRoute = organizationCustomPropertiesAppBuilder.createQueryRouteConfig(
  'businessCustomPropertiesSettingsRoute',
  {
    path: '/enterprises/:business/settings/org-custom-properties',
    queries: [
      mainQuery<BusinessPropertiesSettingsRouteResponse>({
        queryDeps: ({pathname, searchParams}) => ({
          pathname,
          searchParams: {tab: searchParams.get('tab'), page: searchParams.get('page'), q: searchParams.get('q')},
        }),
      }),
    ],
  },
)
