import {mainQuery} from '@github-ui/react-core/future/main-query'
import {organizationCustomPropertiesAppBuilder} from '../config/app-builder'
import type {PropertyDefinition} from '@github-ui/custom-properties-types/org-properties'

export type BusinessPropertyDefinitionRouteResponse = {
  definition: PropertyDefinition | undefined
  propertyNames: string[]
}

export const businessPropertyDefinitionRoute = organizationCustomPropertiesAppBuilder.createQueryRouteConfig(
  'businessPropertyDefinitionRoute',
  {
    path: '/enterprises/:business/settings/org-custom-property/:property_name?',
    queries: [mainQuery<BusinessPropertyDefinitionRouteResponse>()],
  },
)
