import {PropertyPageHeader} from '@github-ui/custom-properties-core/components/PropertyPageHeader'
import {useBannerContext} from '@github-ui/custom-properties-core/context/BannerContext'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useQueryClient} from '@github-ui/react-query'
import {useMemo} from 'react'
import {getOrgSettingsUpdatePropertiesPath} from '../paths'
import {organizationCustomPropertiesSettingsRoute} from './organization-custom-properties-settings-route'
import {PropertiesEditingPage} from '../components/PropertiesEditingPage'

export function OrganizationCustomPropertiesSettingsRoute() {
  const queryClient = useQueryClient()
  const {data, queryKey} = useRouteQuery(organizationCustomPropertiesSettingsRoute, 'mainQuery')
  const {definitions, currentTarget, editableProperties} = data

  const {setBanner, bannerRef} = useBannerContext()

  const editableDefinitions = useMemo(() => {
    const editablePropertiesSet = new Set(editableProperties)
    return definitions.filter(({propertyName}) => editablePropertiesSet.has(propertyName))
  }, [definitions, editableProperties])

  const canEdit = editableDefinitions.length > 0

  // Safe to read the first definition's source because organization custom
  // properties have only one possible source type (enterprise).
  // The "Managed by" label renders only when there is at least one definition,
  // so an empty definitions array requires no special handling.
  const managedBySource = definitions[0]?.source

  return (
    <PropertiesEditingPage
      editingTargets={[currentTarget]}
      definitions={definitions}
      editableProperties={editableProperties}
      onSuccess={() => {
        setBanner('values.updated.success')
        queryClient.invalidateQueries({queryKey})
        window.scrollTo({top: 0})
        // Banner is not visible at this point, so we use setTimeout to focus it in the next render cycle.
        setTimeout(() => bannerRef?.current?.focus())
      }}
      actionLabels={canEdit ? {save: 'Save', cancel: 'Discard'} : {}}
      renderPageHeader={() => (
        <PropertyPageHeader
          title="Custom properties"
          subtitle="Custom properties allow you to decorate your organization with information such as compliance frameworks, data sensitivity, or project details."
        />
      )}
      setValuesPath={getOrgSettingsUpdatePropertiesPath({org: currentTarget.login})}
      managedBySource={managedBySource}
    />
  )
}
