import {PropertyDefinitionForm} from '@github-ui/custom-properties-core/components/PropertyDefinitionForm'
import {createDefinitionForm} from '@github-ui/custom-properties-core/definition-form'
import type {DefinitionFormSchema} from '@github-ui/custom-properties-core/definition-form-types'
import {
  getFirstInvalidFieldKey,
  usePropertyDefinitionForm,
} from '@github-ui/custom-properties-core/hooks/use-property-definition-form'
import {useRefs} from '@github-ui/custom-properties-core/hooks/use-refs'
import type {PropertyDefinition, ValuesEditableBy} from '@github-ui/custom-properties-types/org-properties'
import {useMutation} from '@github-ui/react-query'
import type {SafeHTMLString} from '@github-ui/safe-html'
import sudo from '@github-ui/sudo'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {Checkbox, FormControl} from '@primer/react'
import {useMemo, useState} from 'react'
import {getPropertiesListPath} from '../paths'
import {useBusinessSlug} from '../hooks/use-business-slug'

interface OrgPropertyDefinitionSchema extends DefinitionFormSchema {
  valuesEditableBy: ValuesEditableBy
}

interface Props {
  definition?: PropertyDefinition
  existingPropertyNames: string[]
  setFormError: (error: SafeHTMLString) => void
  onCancel: () => void
  onSuccess: (propertyName: string) => void
}

const form = createDefinitionForm<OrgPropertyDefinitionSchema>()

export function DefinitionForm({definition, existingPropertyNames, setFormError, onCancel, onSuccess}: Props) {
  const {getRef, setRef} = useRefs<OrgPropertyDefinitionSchema>()
  const [saving, setSaving] = useState(false)
  const business = useBusinessSlug()

  const isEditing = Boolean(definition)

  const definitionMutation = useMutation({
    mutationFn: (body: Partial<PropertyDefinition>) => saveDefinition(getPropertiesListPath({business}), body),
    onMutate: () => setSaving(true),
    onSuccess: (_, data) => {
      onSuccess(data.propertyName || '')
    },
    /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- TODO: [SECURITY] Potential XSS risk. Pre-existing infraction - DO NOT COPY. Must be fixed. */
    onError: error => setFormError(error.message as SafeHTMLString),
    onSettled: () => setSaving(false),
  })

  const {updateField, getFieldValue, getFieldError, validateForm, validateField} =
    usePropertyDefinitionForm<OrgPropertyDefinitionSchema>({
      form,
      existingPropertyNames,
      formMode: isEditing ? 'update' : 'create',
      initialValues: {
        propertyName: definition?.propertyName || '',
        description: definition?.description || '',
        valueType: definition?.valueType || 'string',
        allowedValues: definition?.allowedValues || [],
        defaultValue: definition?.defaultValue || '',
        regexEnabled: !!definition?.regex,
        regexPattern: definition?.regex || '',
        required: definition?.required || false,
        newAllowedValue: '',
        valuesEditableBy: definition?.valuesEditableBy || 'enterprise_actors',
      },
    })

  async function onSave() {
    /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Safe empty string reset. SECURITY XSS risk: Do not modify with user input. */
    setFormError('' as SafeHTMLString)
    const errors = await validateForm()

    if (errors.formErrors.length) {
      /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- TODO: [SECURITY] Potential XSS risk. Pre-existing infraction - DO NOT COPY. Must be fixed. */
      return setFormError(errors.formErrors[0] as SafeHTMLString)
    }

    const key = getFirstInvalidFieldKey(errors)
    if (key) {
      return getRef(key)?.focus()
    }

    if (!(await sudo())) {
      /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Static string literal is safe */
      return setFormError('Unauthorized' as SafeHTMLString)
    }

    const valueType = getFieldValue('valueType')
    const allowedValues =
      valueType === 'single_select' || valueType === 'multi_select' ? getFieldValue('allowedValues') : null
    const regex = (getFieldValue('regexEnabled') && getFieldValue('regexPattern')) || null

    const body = {
      propertyName: getFieldValue('propertyName'),
      valueType,
      required: getFieldValue('required'),
      defaultValue: getFieldValue('required') ? getFieldValue('defaultValue') : null,
      description: getFieldValue('description')?.trim() || null,
      allowedValues,
      valuesEditableBy: getFieldValue('valuesEditableBy'),
      regex,
    }

    definitionMutation.mutate(body)
  }

  const valueType = getFieldValue('valueType')
  const isSelect = valueType === 'single_select' || valueType === 'multi_select'
  const isText = valueType === 'string'

  const setNewAllowedValueRef = useMemo(() => setRef('newAllowedValue'), [setRef])

  return (
    <>
      <PropertyDefinitionForm>
        <PropertyDefinitionForm.NameField
          inputRef={setRef('propertyName')}
          readonly={isEditing}
          value={getFieldValue('propertyName')}
          validationError={getFieldError('propertyName')}
          onChange={value => updateField('propertyName', value)}
        />

        <PropertyDefinitionForm.DescriptionField
          inputRef={setRef('description')}
          value={getFieldValue('description') || ''}
          validationError={getFieldError('description')}
          onChange={value => updateField('description', value)}
        />

        <PropertyDefinitionForm.TypeSelector
          value={valueType}
          readonly={isEditing}
          onChange={value => updateField('valueType', value)}
        />

        {isSelect && (
          <PropertyDefinitionForm.AllowedValuesEditor
            setNewAllowedValueRef={setNewAllowedValueRef}
            allowedValues={getFieldValue('allowedValues')}
            newAllowedValue={getFieldValue('newAllowedValue')}
            newAllowedValueError={getFieldError('newAllowedValue')}
            defaultValue={getFieldValue('defaultValue')}
            onNewAllowedValueChange={value => updateField('newAllowedValue', value)}
            onAllowedValuesChange={async ({type, values}) => {
              if (type === 'add') {
                if (await validateField('newAllowedValue')) {
                  return getRef('newAllowedValue')?.focus()
                }
                updateField('newAllowedValue', '', {skipValidation: true})
              }

              updateField('allowedValues', values)
            }}
          />
        )}

        <PropertyDefinitionForm.AdditionalSettingsSection>
          {isText && (
            <PropertyDefinitionForm.RegexEditor
              inputRef={setRef('regexPattern')}
              isEnabled={getFieldValue('regexEnabled')}
              pattern={getFieldValue('regexPattern') || ''}
              validationError={getFieldError('regexPattern')}
              onEnabledChange={enabled => updateField('regexEnabled', enabled)}
              onPatternChange={pattern => updateField('regexPattern', pattern, {debounce: true})}
            />
          )}

          <FormControl>
            <Checkbox
              checked={getFieldValue('valuesEditableBy') === 'enterprise_and_org_actors'}
              onChange={event =>
                updateField(
                  'valuesEditableBy',
                  event.target.checked ? 'enterprise_and_org_actors' : 'enterprise_actors',
                )
              }
            />
            <FormControl.Label>Allow organization actors to set this property</FormControl.Label>
            <FormControl.Caption>
              Organization users and apps with the organization-level &quot;custom properties&quot; fine-grained
              permission can set and update the value for their organization.
            </FormControl.Caption>
          </FormControl>

          <PropertyDefinitionForm.RequiredDefinitionEditor
            checkboxLabel="Require this property for all organizations"
            checkboxCaption="Organizations that don't have an explicit value for this property will inherit the default value."
            defaultValueCaption="This is the default value that will be set for this property."
            setDefaultValueInputRef={setRef('defaultValue')}
            isRequired={getFieldValue('required')}
            valueType={valueType}
            defaultValue={(getFieldValue('defaultValue') || '') as string}
            defaultValueError={getFieldError('defaultValue')}
            allowableDefaultValues={getFieldValue('allowedValues')}
            propertyName={getFieldValue('propertyName')}
            onRequiredChange={required => updateField('required', required)}
            onDefaultValueChange={value => updateField('defaultValue', value, {debounce: true})}
          />
        </PropertyDefinitionForm.AdditionalSettingsSection>

        <PropertyDefinitionForm.Actions isSaving={saving} onSave={onSave} onCancel={onCancel} />
      </PropertyDefinitionForm>
    </>
  )
}

async function saveDefinition(path: string, body: Partial<PropertyDefinition>) {
  const response = await reactFetchJSON(path, {
    method: 'POST',
    body,
  })

  if (response.ok) {
    return
  }

  let errorMessage: string | undefined
  try {
    const data = (await response.json()) as {error?: string}
    errorMessage = data?.error
  } catch {
    errorMessage = 'Something went wrong.'
  }

  // useMutation takes care of the error handling.
  // By re-throwing the error we pipe the error message into the onError handler
  throw new Error(errorMessage)
}
