import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {
  businessCustomPropertiesSettingsRoute,
  type BusinessPropertiesListRouteResponse,
} from './business-custom-properties-settings-route'
import {BusinessSettingsHeader} from '../components/BusinessSettingsHeader'
import {PropertiesPageTabs} from '@github-ui/custom-properties-core/components/PropertiesPageTabs'
import {DefinitionsList} from '@github-ui/custom-properties-core/components/DefinitionsList'
import {getPropertyDetailsPath} from '../paths'
import {useBusinessSlug} from '../hooks/use-business-slug'
import {PropertyTypeFilterProvider, RequiredFilterProvider} from '@github-ui/custom-properties-core/filter-providers'
import {Filter} from '@github-ui/filter'
import {useState} from 'react'
import {Pagination} from '@primer/react'
import {useQuery} from '@github-ui/react-query'
import {queryFnFetch} from '@github-ui/react-core/future/query-fn-fetch'

const filterProviders = [new PropertyTypeFilterProvider(), new RequiredFilterProvider()]

export function BusinessPropertiesListRoute() {
  const {data, currentPage, setFilterValue, setCurrentPage} = useDefinitionListQuery()
  const businessSlug = useBusinessSlug()

  const {definitions, pageCount, totalCount} = data

  return (
    <>
      <BusinessSettingsHeader ownDefinitionsCount={totalCount} />
      <PropertiesPageTabs definitionsCount={totalCount} initialActiveTab="properties" className="tmp-mb-3" />

      <Filter
        id="properties-filter"
        label="Filter properties"
        className="tmp-mb-3"
        providers={filterProviders}
        onSubmit={({raw}) => setFilterValue(raw)}
        variant="input"
      />

      <DefinitionsList
        definitions={definitions}
        totalCount={totalCount}
        renderItem={definition => (
          <DefinitionsList.Item
            key={definition.propertyName}
            linkTo={getPropertyDetailsPath({business: businessSlug, propertyName: definition.propertyName})}
            definition={definition}
          />
        )}
      />

      {pageCount > 1 && (
        <Pagination
          currentPage={currentPage}
          pageCount={pageCount}
          onPageChange={(e, page) => {
            e.preventDefault() // Prevent click event from navigating
            setCurrentPage(page)
          }}
        />
      )}
    </>
  )
}

function useDefinitionListQuery() {
  const {data} = useRouteQuery(businessCustomPropertiesSettingsRoute, 'mainQuery')
  const businessSlug = useBusinessSlug()

  const [touched, setTouched] = useState(false)
  const [filterValue, setFilterValue] = useState('')
  const [currentPage, setCurrentPage] = useState(1)

  // Right now there is no straightforward way to reuse useRouteQuery to refetch data
  // without relying on the search params and URL state.
  // This hook re-fetches the data from the same endpoint on page or query change.
  const {data: searchResult} = useQuery<DefinitionsListData, undefined, BusinessPropertiesListRouteResponse>({
    enabled: touched,
    queryKey: ['definitions-list-results', currentPage, filterValue, businessSlug],
    queryFn: async () =>
      queryFnFetch({
        queryDeps: {
          pathname: businessCustomPropertiesSettingsRoute.generatePath({business: businessSlug}),
          searchParams: {page: `${currentPage}`, q: filterValue},
        },
      }),
    select: tanData => tanData.payload[businessCustomPropertiesSettingsRoute.id],
    placeholderData: prev => prev,
  })

  return {
    data: searchResult || data,
    setFilterValue: (value: string) => {
      setTouched(true)
      setFilterValue(value)
    },
    currentPage,
    setCurrentPage: (page: number) => {
      setTouched(true)
      setCurrentPage(page)
    },
  }
}

interface DefinitionsListData {
  payload: {[businessCustomPropertiesSettingsRoute.id]: BusinessPropertiesListRouteResponse}
}
